import React, { useState } from "react";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

const VendorsPage: React.FC = () => {
  const [vendorData, setVendorData] = useState({
    vendorName: "",
    vendorType: "",
    description: "",
    pricing: "",
    instagramLink: "",
    website: "",
    phone: "",
    email: "",
    availableDates: [],
  });

  const handleDateChange = (dates: Date[]) => {
    setVendorData((prevData) => ({
      ...prevData,
      availableDates: dates,
    }));
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    setVendorData({ ...vendorData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // Handle form submission logic here
  };

  return (
    <div>
      <h2>Vendor Registration</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" name="vendorName" placeholder="Vendor Name" value={vendorData.vendorName} onChange={handleChange} required />
        <select name="vendorType" value={vendorData.vendorType} onChange={handleChange} required>
          <option value="">Select Vendor Type</option>
          <option value="Venue">Venue</option>
          <option value="Caterer">Caterer</option>
          {/* Add more vendor types here */}
        </select>
        {/* Other vendor fields */}
        <label>Select Available Dates:</label>
        <DatePicker
          selected={vendorData.availableDates}
          onChange={handleDateChange}
          isClearable
          multiple
          placeholderText="Select Dates"
        />
        <button type="submit">Submit</button>
      </form>
    </div>
  );
};

export default VendorsPage;


